const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '20' },
      { kind: 'text', payload: '40' },
      { kind: 'text', payload: '60' },
      { kind: 'text', payload: '80' },
      { kind: 'text', payload: '100' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.max(28, Math.min(80, w * 0.1));
    var x0 = margin;
    var x1 = w - margin;
    var axisY = h * 0.55;
    var axis = visualSdk.axis({
      x0: x0,
      y0: axisY,
      x1: x1,
      y1: axisY,
      ticks: 6,
      tickLength: 12
    });
    var children = [
      {
        type: 'path',
        pathId: 'axis',
        fill: '#26354a',
        stroke: { width: 2, cap: 'round' }
      }
    ];
    for (var i = 0; i < metrics.length; i++) {
      var t = i / (metrics.length - 1);
      var x = x0 + (x1 - x0) * t;
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: axisY + 28 },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-axis',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'axis', commands: axis }
      ],
      root: {
        type: 'group',
        children: children
      }
    };
  }
};
